INSERT INTO public.projects (slug,title,category,location,project_date,description,challenge,solution,cover_image_url,gallery,features,sort_order,is_visible)
VALUES
('modern-villa','Modern Apartment Interior','Residential','Ahmedabad','July 2024','A contemporary apartment featuring custom plywood furniture, premium hardware fittings, and modern design elements. This project showcases our expertise in creating luxurious living spaces.','The main challenge was maximizing space utilization while maintaining a luxurious feel.','We implemented a sophisticated design approach using premium materials and smart space planning.','https://images.unsplash.com/photo-1600585154526-990dced4db0d?auto=format&fit=crop&w=1200&q=80','[{"url":"https://images.unsplash.com/photo-1600607687644-c7171b42498f?auto=format&fit=crop&w=1200&q=80","caption":"Master Bedroom with Custom Headboard"},{"url":"https://images.unsplash.com/photo-1600566753086-00f18fb6b3ea?auto=format&fit=crop&w=1200&q=80","caption":"Modern Kitchen Design"}]'::jsonb,'["Custom plywood furniture with premium finishes","LED strip lighting and recessed spotlights","Built-in storage solutions","Premium finishes"]'::jsonb,1,true),
('bungalow-makeover','Bungalow Makeover','Residential','Ahmedabad','August 2024','A complete bungalow transformation with modern furniture, comfortable gathering areas, and smart storage ideas.','The challenge was balancing open entertaining areas with private spaces.','We created a flexible layout with movable furniture and carefully planned acoustic separation.','https://images.unsplash.com/photo-1497366216548-37526070297c?auto=format&fit=crop&w=1200&q=80','[{"url":"https://images.unsplash.com/photo-1600566752355-35792bedcfea?auto=format&fit=crop&w=1200&q=80","caption":"Elegant Bedroom"},{"url":"https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?auto=format&fit=crop&w=1200&q=80","caption":"Modular Kitchen"}]'::jsonb,'["Custom workstations with cable management","Premium storage solutions","LED lighting systems","Smart space utilization"]'::jsonb,2,true),
('luxury-apartment','Luxury Apartment Renovation','Residential','Ahmedabad','September 2024','A high-end apartment renovation showcasing premium materials, custom cabinetry, and sophisticated design elements.','Integrating modern amenities while preserving the classic architectural elements of the space.','We blended contemporary design with traditional elements using high-end materials and custom furniture.','https://images.unsplash.com/photo-1600566752355-35792bedcfea?auto=format&fit=crop&w=1200&q=80','[{"url":"https://images.unsplash.com/photo-1600607687920-4e2a09cf159d?auto=format&fit=crop&w=1200&q=80","caption":"Grand Living Room"},{"url":"https://images.unsplash.com/photo-1600607688969-a5bfcd646154?auto=format&fit=crop&w=1200&q=80","caption":"Master Suite"}]'::jsonb,'["Custom millwork throughout","Smart home integration","Premium stone surfaces","Luxury finishes"]'::jsonb,3,true),
('modern-design-villa','Latest Attractive Design Villa','Residential','Ahmedabad','October 2024','An elegant villa interior featuring custom woodwork, ambient bedrooms and bathrooms, and a sophisticated dining space.','The difficulty was giving each room a distinct style while keeping one cohesive villa experience.','Custom woodwork and lighting create a special mood in each room while shared details maintain flow.','https://images.unsplash.com/photo-1600607687920-4e2a09cf159d?auto=format&fit=crop&w=1200&q=80','[{"url":"https://images.unsplash.com/photo-1615873968403-89e068629265?auto=format&fit=crop&w=1200&q=80","caption":"Grand Bedroom"},{"url":"https://images.unsplash.com/photo-1615876234886-fd9a39fda97f?auto=format&fit=crop&w=1200&q=80","caption":"Elegant Interior"}]'::jsonb,'["Custom wood paneling","Ambient lighting design","Premium seating solutions","Designer furniture"]'::jsonb,4,true)
