('about','{"hero_title":"About Us","hero_background":"https://images.unsplash.com/photo-1611892440504-42a792e24d32?auto=format&fit=crop&q=80","content_background":"https://images.unsplash.com/photo-1615873968403-89e068629265?auto=format&fit=crop&q=80","story_title":"Our Story","story_html":"<p>For over two decades, we have been at the forefront of the woodworking and construction industry, delivering exceptional quality and craftsmanship to our clients.</p><p>We source the finest materials, employ skilled craftsmen, and deliver projects that exceed expectations.</p>","values_title":"Our Values","values":["Unwavering commitment to quality","Transparent communication throughout the project","Innovation in design and execution","Sustainable practices and materials","Customer satisfaction above all"]}'::jsonb),
('contact','{"hero_title":"Contact Us","hero_background":"https://images.unsplash.com/photo-1600607687644-c7171b42498f?auto=format&fit=crop&q=80","content_background":"https://images.unsplash.com/photo-1600566753086-00f18fb6b3ea?auto=format&fit=crop&q=80","form_title":"Tell us about your project","success_message":"Thanks for reaching out. We will get back to you soon."}'::jsonb)
